// Transparent vignette overlay — clear centre, darkening toward the edges.
uniform float uStrength; // @param 0.75 0 1
uniform float uRadius;   // @param 0.45 0 1.5
uniform float uSoftness; // @param 0.5 0.01 1.5
uniform vec3  uColor;    // @param #000000

void main() {
  // Aspect-corrected distance from centre (short axis spans -0.5..0.5)
  vec2 p = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  float d = length(p);

  // Fully transparent inside the radius: bail out early
  if (d <= uRadius) {
    fragColor = vec4(0.0);
    return;
  }

  float t = smoothstep(uRadius, uRadius + uSoftness, d);
  float a = clamp(t * uStrength, 0.0, 1.0);
  // Premultiplied colour (default black is also correct for straight alpha)
  fragColor = vec4(uColor * a, a);
}
